/**
 * Fast search helper that filters by symbol, name, or subIndustry.
 * Matches starting with symbol are prioritized first.
 */
export function searchSP500Stocks(query: string, sector?: string, limit = 50): SP500Stock[] {
  const clean = query.trim().toUpperCase();
  const cleanLow = query.trim().toLowerCase();

  return SP500_STOCKS.filter((stock) => {
    if (sector && sector !== 'Todos' && stock.sector !== sector) {
      return false;
    }
    if (!clean) return true;
    return (
      stock.symbol.toUpperCase().includes(clean) ||
      stock.name.toLowerCase().includes(cleanLow) ||
      stock.subIndustry.toLowerCase().includes(cleanLow)
    );
  }).sort((a, b) => {
    // Exact symbol match first
    if (a.symbol === clean) return -1;
    if (b.symbol === clean) return 1;
    // Starts with symbol next
    const aStarts = a.symbol.startsWith(clean);
    const bStarts = b.symbol.startsWith(clean);
    if (aStarts && !bStarts) return -1;
    if (!aStarts && bStarts) return 1;
    // Megacaps prioritized
    if (a.isMegacap && !b.isMegacap) return -1;
    if (!a.isMegacap && b.isMegacap) return 1;
    return a.symbol.localeCompare(b.symbol);
  }).slice(0, limit);
}

/**
 * Returns sector summary counts
 */
export function getSP500SectorCounts(): Record<string, number> {
  const counts: Record<string, number> = { Todos: SP500_STOCKS.length };
  for (const stock of SP500_STOCKS) {
    counts[stock.sector] = (counts[stock.sector] || 0) + 1;
  }
  return counts;
}

/**
 * Quick lookup helper
 */
export function findSP500Stock(symbol: string): SP500Stock | undefined {
  const clean = symbol.trim().toUpperCase().replace('/', '.').replace('-', '.');
  return SP500_STOCKS.find((s) => s.symbol.toUpperCase() === clean || s.symbol.replace('.', '-').toUpperCase() === clean);
}
